//! The shared core of the INVIZENT phone apps.
//!
//! One implementation, used by the iOS (Swift) and Android (Kotlin) apps, of everything that must behave
//! identically on both: the server protocol and the logic around end-to-end encryption. The reference for
//! every piece is the TypeScript app in `mobile/src` and the server in `server/src`; each module here is pinned
//! to that reference by vectors produced by running the reference itself (`tests/vectors`, generated by
//! `tests/generate-vectors.mjs`).

pub mod api;
pub mod attest;
pub mod chat_view;
pub mod device_proof;
pub mod e2ee;
pub mod ffi;
pub mod http;
#[cfg(target_os = "android")] mod jni;
pub mod json;
pub mod media;
pub mod message_meta;
pub mod network;
pub mod photo;
pub mod servers;
#[cfg(feature = "signal")]
pub mod signal;
pub mod time;
